  function arrivalsForYear(year){const out=[];for(const p of state.pool){if(p.dynastyCareer?.debutYear===year&&!p.dynastyRetired){p.available=true;p.draftedBy=null;applyCareerYear(p,year);out.push(p);log('NEW PLAYER',`${p.name} enters the GCC player pool`,`${p.country} · ${p.role}`,'good')}}return out.sort((a,b)=>b.overall-a.overall)}
