  function renderReady(){$('dynastyMain').innerHTML=`<section class="dynasty-card"><span class="kicker">PRE-SEASON</span><h3>The 15 are lodged.</h3><p>Now name the XI that opens the season. Form carries over lightly; selection starts again.</p><div class="dynasty-actions"><button class="button primary" onclick="Dynasty.enterTeamRoom()">NAME THE ${state.year} XI</button><button class="button" onclick="Dynasty.openArchive()">CHECK THE ARCHIVE</button></div></section>`}
