  function statusBadge(p){const i=injury(p.id),f=p.form||0;const bits=[];if(i)bits.push(`<span class="dynasty-badge ${i.status.toLowerCase()}">${i.status}${i.status==='OUT'?` · ${i.roundsLeft}R`:''}</span>`);if(f>=2)bits.push('<span class="dynasty-badge hot">HOT FORM</span>');else if(f<=-2)bits.push('<span class="dynasty-badge cold">COLD FORM</span>');return bits.length?`<div class="player-dynasty-badges">${bits.join('')}</div>`:''}
